-- The daily digest (#332), the "important" flag (#333) and the kind names the
-- marks use (#331) shipped without translations (#350).
--
-- The kind names and the digest section headings are composed at runtime
-- (push_t($lang, 'itemkind_' . $kind)), which is why nothing noticed they were
-- missing until bin/texte-pruefen.php learned to follow a prefix.
SET NAMES utf8mb4;

